@@ -0,0 +1,254 @@
+#!/usr/bin/env node
+
+import { realpathSync } from "node:fs";
+import { cp, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
+import { existsSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join, resolve } from "node:path";
+import { fileURLToPath } from "node:url";
+import { exportStaticSite } from "../../src/api/snapshot.ts";
+import { openReview } from "../../src/api/live.ts";
+import { cmdValidate } from "../../src/cli/commands.ts";
+import { git } from "../../src/git/exec.ts";
+import { findPackageRoot } from "../../src/package-root.ts";
+import { loadDocument } from "../../src/review/load.ts";
+import { EVAL_USAGE, parseEvalArgv } from "./args.ts";
+import { listEvalCases, selectEvalCases, type EvalCase } from "./case.ts";
+import { loadFrozenSourceValues, runDeterministicChecks } from "./checks.ts";
+import { addDetachedWorktree, ensureBareClone, fetchCaseRefs, removeWorktree, thisRepoMirror } from "./clone.ts";
+import { groupingPrompt, prosePrompt, runGrader } from "./graders.ts";
+import { parseGithubRepoRemote } from "./github.ts";
+import { writeGradingPacket } from "./packet.ts";
+import { producerPrompt, runProducer } from "./producer.ts";
+import {
+  caseFailed,
+  claimsFromGrader,
+  formatBaselineDelta,
+  formatCaseLine,
+  writeCaseArtifacts,
+  type CaseResult,
+  type RunSummary,
+} from "./result.ts";
+import { copySkillForEval, readNextSkillMd } from "./skill.ts";
+
+export async function runEval(argv: string[], packageRoot = findPackageRoot()): Promise<number> {
+  const request = parseEvalArgv(argv);
+  if (request.kind === "help") {
+    console.log(EVAL_USAGE);
+    return 0;
+  }
+  if (request.kind === "error") {
+    console.error(request.message);
+    console.error(`\n${EVAL_USAGE}`);
+    return 1;
+  }
+  const apiKey = process.env.CURSOR_API_KEY;
+  if (apiKey === undefined || apiKey === "") {
+    console.error("CURSOR_API_KEY is not set");
+    return 1;
+  }
+  const casesDir = join(packageRoot, "eval/cases");
+  const selected = selectEvalCases(await listEvalCases(casesDir), { ids: request.ids, tag: request.tag });
+  if (selected.length === 0) {
+    console.error("no eval cases matched");
+    return 1;
+  }
+  const stamp = new Date().toISOString().replaceAll(/[:.]/g, "-");
+  const runDir = join(packageRoot, "eval/runs", stamp);
+  await mkdir(runDir, { recursive: true });
+  const skillTree = (await git(packageRoot, ["rev-parse", "HEAD:skills-next/comprehende"])).trim();
+  const skillMd = await readNextSkillMd(packageRoot);
+  const summary: RunSummary = {
+    stamp,
+    skillTree,
+    producerModel: request.producerModel,
+    graderModel: request.graderModel,
+    cases: [],
+  };
+  for (const item of selected) {
+    const result = await evalOneCase({
+      packageRoot,
+      runDir,
+      spec: item.spec,
+      caseDir: item.dir,
+      skillMd,
+      producerModel: request.producerModel,
+      graderModel: request.graderModel,
+      sandbox: request.sandbox,
+      apiKey,
+    });
+    summary.cases.push(result);
+    console.log(formatCaseLine(result));
+  }
+  await writeFile(join(runDir, "summary.json"), `${JSON.stringify(summary, null, 2)}\n`);
+  console.error(`wrote ${runDir}`);
+  if (request.baseline !== undefined) {
+    await printBaseline(request.baseline, summary);
+  }
+  if (request.json) {
+    console.log(JSON.stringify(summary, null, 2));
+  }
+  return summary.cases.some(caseFailed) ? 1 : 0;
+}
+
+async function evalOneCase(opts: {
+  packageRoot: string;
+  runDir: string;
+  spec: EvalCase;
+  caseDir: string;
+  skillMd: string;
+  producerModel: string;
+  graderModel: string;
+  sandbox: boolean;
+  apiKey: string;
+}): Promise<CaseResult> {
+  const started = Date.now();
+  const result: CaseResult = { id: opts.spec.id, ok: true, durationMs: 0, tokens: 0 };
+  const caseOut = join(opts.runDir, opts.spec.id);
+  await mkdir(caseOut, { recursive: true });
+  const tmp = await mkdtemp(join(tmpdir(), `comprehende-eval-${opts.spec.id}-`));
+  const repoCwd = join(tmp, "repo");
+  const cacheDir = join(opts.packageRoot, "eval/.cache");
+  let bare: string | undefined;
+  try {
+    bare = await ensureBareClone({
+      cacheDir,
+      repoUrl: opts.spec.repo,
+      localMirror: await thisRepoMirror(opts.packageRoot, opts.spec.repo),
+    });
+    await fetchCaseRefs(bare, opts.spec.pr, opts.spec.base, opts.spec.head);
+    await addDetachedWorktree(bare, repoCwd, opts.spec.head);
+    const cliPath = join(opts.packageRoot, "dist/cli/main.js");
+    if (!existsSync(cliPath)) {
+      throw new Error("dist/cli/main.js is missing. pnpm eval runs the build first.");
+    }
+    const skillDir = join(tmp, "skill");
+    const sourcesDir = join(tmp, "sources");
+    const reviewPath = join(tmp, "out/review.json");
+    await copySkillForEval(opts.packageRoot, skillDir, cliPath);
+    await mkdir(join(tmp, "out"), { recursive: true });
+    const caseSources = join(opts.caseDir, "sources");
+    if (existsSync(caseSources)) {
+      await cp(caseSources, sourcesDir, { recursive: true });
+    } else {
+      await mkdir(sourcesDir);
+    }
+    const producer = await runProducer({
+      repoCwd,
+      model: opts.producerModel,
+      apiKey: opts.apiKey,
+      sandbox: opts.sandbox,
+      prompt: producerPrompt({
+        skillMd: join(skillDir, "SKILL.md"),
+        sourcesDir,
+        outPath: reviewPath,
+        base: opts.spec.base,
+        head: opts.spec.head,
+      }),
+    });
+    result.producer = producer;
+    await writeFile(join(caseOut, "producer.md"), producer.text);
+    if (producer.status !== "finished" || producer.error !== undefined) {
+      result.producerError = producer.error ?? `producer status ${producer.status}`;
+    } else if (!existsSync(reviewPath)) {
+      result.producerError = `producer did not write ${reviewPath}`;
+    }
+
+    if (existsSync(reviewPath)) {
+      await cp(reviewPath, join(caseOut, "review.json"));
+      try {
+        await cmdValidate(repoCwd, reviewPath);
+      } catch (error) {
+        result.validateError = error instanceof Error ? error.message : String(error);
+      }
+      try {
+        const document = await loadDocument(reviewPath);
+        result.document = { title: document.title, size: document.size, why: document.why };
+        const frozen = await loadFrozenSourceValues(sourcesDir);
+        result.checks = await runDeterministicChecks({
+          cwd: repoCwd,
+          document,
+          expect: opts.spec.expect,
+          frozen,
+          repo: parseGithubRepoRemote(opts.spec.repo),
+        });
+        const ctx = await openReview(repoCwd, document);
+        const packetPath = join(caseOut, "packet.md");
+        await writeGradingPacket(ctx, frozen, packetPath);
+        const [grouping, prose] = await Promise.all([
+          runGrader({
+            repoCwd,
+            model: opts.graderModel,
+            apiKey: opts.apiKey,
+            sandbox: opts.sandbox,
+            prompt: groupingPrompt({ skillMd: opts.skillMd, packetPath }),
+          }),
+          runGrader({
+            repoCwd,
+            model: opts.graderModel,
+            apiKey: opts.apiKey,
+            sandbox: opts.sandbox,
+            prompt: prosePrompt({
+              skillMd: opts.skillMd,
+              packetPath,
+              claims: opts.spec.expect?.claims ?? [],
+            }),
+          }),
+        ]);
+        result.grouping = grouping;
+        result.prose = prose;
+        await writeFile(join(caseOut, "grouping.json"), `${JSON.stringify(grouping, null, 2)}\n`);
+        await writeFile(join(caseOut, "prose.json"), `${JSON.stringify(prose, null, 2)}\n`);
+        result.claims = claimsFromGrader(opts.spec.expect?.claims, prose);
+        const site = join(caseOut, "site");
+        await exportStaticSite({ cwd: repoCwd, dataPath: reviewPath, outDir: site, ctx });
+        result.site = site;
+      } catch (error) {
+        result.validateError ??= error instanceof Error ? error.message : String(error);
+      }
+    }
+  } catch (error) {
+    result.producerError ??= error instanceof Error ? error.message : String(error);
+  } finally {
+    if (bare !== undefined) {
+      await removeWorktree(bare, repoCwd);
+    }
+    await rm(tmp, { recursive: true, force: true });
+  }
+  result.ok = !caseFailed(result);
+  result.tokens = (result.producer?.tokens ?? 0) + (result.grouping?.run.tokens ?? 0) + (result.prose?.run.tokens ?? 0);
+  result.durationMs = Date.now() - started;
+  await writeCaseArtifacts(caseOut, result, {});
+  return result;
+}
+
+async function printBaseline(baselineDir: string, summary: RunSummary): Promise<void> {
+  const previous = JSON.parse(await readFile(join(resolve(baselineDir), "summary.json"), "utf8")) as RunSummary;
+  const byId = new Map(previous.cases.map((item) => [item.id, item]));
+  console.log("baseline deltas");
+  for (const item of summary.cases) {
+    const line = formatBaselineDelta(item, byId.get(item.id));
+    if (line !== undefined) {
+      console.log(line);
+    }
+  }
+}
+
+const thisFile = fileURLToPath(import.meta.url);
+if (isEvalCliEntry(thisFile, process.argv[1])) {
+  process.exitCode = await runEval(process.argv.slice(2));
+}
+
+export function isEvalCliEntry(modulePath: string, argv1: string | undefined): boolean {
+  if (argv1 === undefined) {
+    return false;
+  }
+  try {
+    if (realpathSync(modulePath) === realpathSync(argv1)) {
+      return true;
+    }
+  } catch {
+    // tsx shims
+  }
+  return resolve(argv1).replaceAll("\\", "/").endsWith("scripts/eval/run.ts");
+}

diff --git a/scripts/eval/result.ts b/scripts/eval/result.ts
new file mode 100644
index 0000000..b040f0f
--- /dev/null
+++ b/scripts/eval/result.ts
@@ -0,0 +1,165 @@
+import { mkdir, writeFile } from "node:fs/promises";
+import { join } from "node:path";
+import type { ReviewDocument } from "../../src/schema/types.ts";
+import type { DeterministicReport } from "./checks.ts";
+import type { AgentRunResult } from "./agent.ts";
+import type { Finding, GraderResult } from "./graders.ts";
+
+export type CaseResult = {
+  id: string;
+  ok: boolean;
+  durationMs: number;
+  tokens: number;
+  producer?: AgentRunResult;
+  producerError?: string;
+  validateError?: string;
+  document?: Pick<ReviewDocument, "title" | "size" | "why">;
+  checks?: DeterministicReport;
+  grouping?: GraderResult;
+  prose?: GraderResult;
+  claims?: { stated: number; total: number; missing: string[] };
+  site?: string;
+};
+
+export type RunSummary = {
+  stamp: string;
+  skillTree: string;
+  producerModel: string;
+  graderModel: string;
+  cases: CaseResult[];
+};
+
+export function caseFailed(result: CaseResult): boolean {
+  if (result.producerError !== undefined || result.validateError !== undefined) {
+    return true;
+  }
+  return (result.checks?.failures.length ?? 0) > 0;
+}
+
+export function formatCaseLine(result: CaseResult): string {
+  const bits = [result.id];
+  if (result.producerError !== undefined) {
+    bits.push("producer FAIL");
+  } else {
+    bits.push(result.validateError === undefined ? "validate ok" : "validate FAIL");
+  }
+  const checks = result.checks;
+  if (checks !== undefined) {
+    bits.push(failed(checks, "sources") ? "sources FAIL" : "sources ok");
+    bits.push(failed(checks, "why") ? `why ${checks.why} FAIL` : `why ${checks.why}`);
+    bits.push(failed(checks, "parts") ? `parts ${checks.parts} FAIL` : `parts ${checks.parts}`);
+    bits.push(failed(checks, "size") ? `size ${checks.size} FAIL` : `size ${checks.size}`);
+    bits.push(`together ${checks.togetherOk}/${checks.togetherTotal}`);
+    bits.push(`apart ${checks.apartOk}/${checks.apartTotal}`);
+    if (failed(checks, "worktree")) {
+      bits.push("worktree dirty");
+    }
+    const lints = checks.failures.filter((item) => item.check === "proseLint").length;
+    if (lints > 0) {
+      bits.push(`lint ${lints}`);
+    }
+  }
+  if (result.claims !== undefined) {
+    bits.push(`claims ${result.claims.stated}/${result.claims.total}`);
+  }
+  bits.push(findingCounts("grouping", result.grouping));
+  bits.push(findingCounts("prose", result.prose));
+  bits.push(formatDuration(result.durationMs));
+  bits.push(formatTokens(result.tokens));
+  return bits.join("  ");
+}
+
+export function formatBaselineDelta(current: CaseResult, previous: CaseResult | undefined): string | undefined {
+  if (previous === undefined) {
+    return `${current.id}  new`;
+  }
+  const bits: string[] = [];
+  if (caseFailed(current) !== caseFailed(previous)) {
+    bits.push(caseFailed(current) ? "now FAIL" : "now ok");
+  }
+  const curFail = current.checks?.failures.length ?? 0;
+  const prevFail = previous.checks?.failures.length ?? 0;
+  if (curFail !== prevFail) {
+    bits.push(`checks ${prevFail}->${curFail}`);
+  }
+  const curG = countFindings(current.grouping);
+  const prevG = countFindings(previous.grouping);
+  if (curG.major !== prevG.major || curG.minor !== prevG.minor) {
+    bits.push(`grouping ${prevG.major}M${prevG.minor}m->${curG.major}M${curG.minor}m`);
+  }
+  const curP = countFindings(current.prose);
+  const prevP = countFindings(previous.prose);
+  if (curP.major !== prevP.major || curP.minor !== prevP.minor) {
+    bits.push(`prose ${prevP.major}M${prevP.minor}m->${curP.major}M${curP.minor}m`);
+  }
+  if (bits.length === 0) {
+    return undefined;
+  }
+  return `${current.id}  ${bits.join("  ")}`;
+}
+
+export async function writeCaseArtifacts(dir: string, result: CaseResult, extras: Record<string, string>): Promise<void> {
+  await mkdir(dir, { recursive: true });
+  await writeFile(join(dir, "result.json"), `${JSON.stringify(result, null, 2)}\n`);
+  for (const [name, body] of Object.entries(extras)) {
+    await writeFile(join(dir, name), body);
+  }
+}
+
+function failed(report: DeterministicReport, check: string): boolean {
+  return report.failures.some((item) => item.check === check);
+}
+
+function findingCounts(label: string, grader: GraderResult | undefined): string {
+  if (grader === undefined) {
+    return `${label} -`;
+  }
+  if (grader.parseError !== undefined) {
+    return `${label} parse FAIL`;
+  }
+  const { major, minor } = countFindings(grader);
+  return `${label} ${major}M ${minor}m`;
+}
+
+function countFindings(grader: GraderResult | undefined): { major: number; minor: number } {
+  const findings: Finding[] = grader?.output.findings ?? [];
+  return {
+    major: findings.filter((item) => item.severity === "major").length,
+    minor: findings.filter((item) => item.severity === "minor").length,
+  };
+}
+
+export function formatDuration(ms: number): string {
+  const seconds = Math.max(0, Math.round(ms / 1000));
+  if (seconds < 60) {
+    return `${seconds}s`;
+  }
+  const minutes = Math.floor(seconds / 60);
+  const rest = seconds % 60;
+  return `${minutes}m${String(rest).padStart(2, "0")}s`;
+}
+
+export function formatTokens(tokens: number): string {
+  if (tokens < 1000) {
+    return `${tokens} tok`;
+  }
+  return `${Math.round(tokens / 1000)}k tok`;
+}
+
+export function claimsFromGrader(expected: string[] | undefined, grader: GraderResult | undefined): CaseResult["claims"] {
+  if (expected === undefined || expected.length === 0) {
+    return undefined;
+  }
+  const verdicts = grader?.output.claims ?? [];
+  const missing: string[] = [];
+  let stated = 0;
+  for (const claim of expected) {
+    const hit = verdicts.find((item) => item.claim === claim);
+    if (hit?.stated === true) {
+      stated += 1;
+    } else {
+      missing.push(claim);
+    }
+  }
+  return { stated, total: expected.length, missing };
+}
